import React, { useState, useEffect } from 'react';
import { ordersApi, billsApi } from '../utils/api';
import toast from 'react-hot-toast';

const STRATEGIES = [
  { value: 'standard', label: 'Standard Pricing' },
  { value: 'happyhour', label: 'Happy Hour (-20%)' },
  { value: 'loyalty', label: 'Loyalty Card (-10% + free drink)' },
  { value: 'group', label: 'Group Discount (-15%)' },
];

export default function BillModal({ table, onClose }) {
  const [tableOrders, setTableOrders] = useState([]);
  const [selectedOrder, setSelectedOrder] = useState('');
  const [strategy, setStrategy] = useState('standard');
  const [tipPercent, setTipPercent] = useState('');
  const [guests, setGuests] = useState('1');
  const [bill, setBill] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    ordersApi.getAll({ tableId: String(table.id) }).then((data) => {
      const billable = data.filter((o) => ['confirmed', 'in_preparation', 'ready', 'served'].includes(o.status));
      setTableOrders(billable);
      if (billable.length > 0) setSelectedOrder(billable[0].id);
    });
  }, [table.id]);

  async function handleGenerateBill() {
    if (!selectedOrder) { toast.error('Select an order'); return; }
    setSubmitting(true);
    try {
      const data = await billsApi.create({
        orderId: selectedOrder,
        pricingStrategy: strategy,
        tipPercent: tipPercent ? parseFloat(tipPercent) : undefined,
        guests: parseInt(guests) || 1,
      });
      setBill(data);
      toast.success('Bill generated');
    } catch (err) {
      toast.error(err.response?.data?.error || 'Failed to generate bill');
    } finally {
      setSubmitting(false);
    }
  }

  async function handlePay() {
    if (!bill) return;
    try {
      await billsApi.pay(bill.id);
      toast.success('Payment processed — table cleared');
      onClose();
    } catch (err) {
      toast.error(err.response?.data?.error || 'Failed to process payment');
    }
  }

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <h3 className="text-xl font-bold text-white mb-4">Billing — Table {table.id}</h3>

        {!bill ? (
          <>
            {tableOrders.length === 0 ? (
              <p className="text-gray-400">No billable orders found for this table.</p>
            ) : (
              <>
                <div className="mb-3">
                  <label className="label">Order</label>
                  <select className="input w-full" value={selectedOrder} onChange={(e) => setSelectedOrder(e.target.value)}>
                    {tableOrders.map((o) => (
                      <option key={o.id} value={o.id}>
                        #{o.id.slice(0, 8)} — ${o.total.toFixed(2)} ({o.status})
                      </option>
                    ))}
                  </select>
                </div>
                <div className="mb-3">
                  <label className="label">Pricing Strategy</label>
                  <select className="input w-full" value={strategy} onChange={(e) => setStrategy(e.target.value)}>
                    {STRATEGIES.map((s) => (
                      <option key={s.value} value={s.value}>{s.label}</option>
                    ))}
                  </select>
                </div>
                <div className="flex gap-3 mb-3">
                  <div className="flex-1">
                    <label className="label">Tip %</label>
                    <input className="input w-full" type="number" min="0" max="100" placeholder="0" value={tipPercent} onChange={(e) => setTipPercent(e.target.value)} />
                  </div>
                  <div className="flex-1">
                    <label className="label">Split Guests</label>
                    <input className="input w-full" type="number" min="1" max="20" value={guests} onChange={(e) => setGuests(e.target.value)} />
                  </div>
                </div>
                <button
                  onClick={handleGenerateBill}
                  disabled={submitting}
                  className="btn w-full bg-purple-600 hover:bg-purple-500 text-white mb-2"
                >
                  {submitting ? 'Generating...' : 'Generate Bill'}
                </button>
              </>
            )}
            <button onClick={onClose} className="btn w-full bg-gray-700 hover:bg-gray-600 text-white">Cancel</button>
          </>
        ) : (
          <>
            <div className="bg-gray-800 rounded-xl p-4 mb-4">
              <div className="flex justify-between text-gray-300 text-sm mb-1">
                <span>Strategy</span><span className="text-amber-400">{bill.strategyName}</span>
              </div>
              {bill.lineItems.map((item, i) => (
                <div key={i} className="flex justify-between text-sm text-gray-300 py-1 border-b border-gray-700">
                  <span>{item.description}</span>
                  <span className={item.amount < 0 ? 'text-red-400' : 'text-white'}>${item.amount.toFixed(2)}</span>
                </div>
              ))}
              <div className="flex justify-between text-sm text-gray-400 mt-2">
                <span>Subtotal</span><span>${bill.subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm text-gray-400">
                <span>Tax (8%)</span><span>${bill.tax.toFixed(2)}</span>
              </div>
              {bill.tip > 0 && (
                <div className="flex justify-between text-sm text-gray-400">
                  <span>Tip</span><span>${bill.tip.toFixed(2)}</span>
                </div>
              )}
              <div className="flex justify-between text-lg font-bold text-white mt-3 pt-3 border-t border-gray-600">
                <span>Total</span><span className="text-emerald-400">${bill.total.toFixed(2)}</span>
              </div>
              {bill.perGuest && (
                <div className="flex justify-between text-sm text-amber-300 mt-1">
                  <span>Per guest ({bill.guestCount})</span><span>${bill.perGuest.toFixed(2)}</span>
                </div>
              )}
            </div>
            <button onClick={handlePay} className="btn w-full bg-emerald-600 hover:bg-emerald-500 text-white mb-2">
              Process Payment
            </button>
            <button onClick={onClose} className="btn w-full bg-gray-700 hover:bg-gray-600 text-white">Close</button>
          </>
        )}
      </div>
    </div>
  );
}
